package com.shopstream.demo;

import java.nio.charset.StandardCharsets;
import java.util.List;
import org.apache.kafka.common.utils.Utils;

public class WhichPartition {

    static int partitionFor(String key, int numPartitions) {
        byte[] keyBytes = key.getBytes(StandardCharsets.UTF_8);
        return Utils.toPositive(Utils.murmur2(keyBytes)) % numPartitions;
    }

    public static void main(String[] args) {
        List<String> keys = List.of("o-1001", "o-1002", "o-1003", "o-1004", "o-1005", "o-1006");
        for (String key : keys) {
            System.out.printf("%s  3 partitions -> %d   4 partitions -> %d%n",
                    key, partitionFor(key, 3), partitionFor(key, 4));
        }
    }
}
